import java.io.*;
public class DeserializationConstructorDemo {
    static class Tile implements Serializable {
        static int constructorCalls;
        String id;
        Tile(String id) { constructorCalls++; this.id=id; }
    }
    public static void main(String[] args) throws Exception {
        Tile original = new Tile("T1");
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try(ObjectOutputStream out = new ObjectOutputStream(bytes)) { out.writeObject(original); }
        Tile.constructorCalls = 0;
        try(ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
            Tile restored = (Tile) in.readObject();
            System.out.println(restored.id + ":" + Tile.constructorCalls);
        }
    }
}
